<template><view><view class="row-between"><view class="section-title">活动相册</view><button size="mini" class="mini-primary" @click="choose">上传照片</button></view><view class="grid"><image v-for="(p,i) in photos" :key="p.id" class="photo" :src="p.url" mode="aspectFill" @click="preview(i)" /></view><view v-if="!photos.length" class="empty">暂无照片</view></view></template>
<script setup lang="ts">import{ref,watch}from'vue';import{api,upload}from'@/services/api';import type{Photo}from'@/services/types';const props=defineProps<{activityId:number;refreshKey:number}>(),photos=ref<Photo[]>([]);async function load(){photos.value=await api(`/activities/${props.activityId}/photos`)}watch(()=>props.refreshKey,load,{immediate:true});function choose(){uni.chooseImage({count:1,sizeType:['compressed'],success:async r=>{await upload(`/activities/${props.activityId}/photos`,r.tempFilePaths[0]);await load()}})}function preview(i:number){uni.previewImage({current:i,urls:photos.value.map(p=>p.url)})}</script>
<style scoped>.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12rpx}.photo{width:100%;height:210rpx;border-radius:12rpx}</style>
